practiceBank.solution:
#include <iostream>
#include <vector>
#include <string>
int main() {
    int a, b; std::cin >> a >> b;
    while (b != 0) { int r = a % b; a = b; b = r; } int answer = a; std::cout << answer << "\n";
}

