practiceBank.solution:
#include <iostream>
#include <vector>
#include <string>
int main() {
    int n; std::cin >> n;
    int answer = 0; for (int i = 1; i <= n; i++) if (i % 3 == 0) answer += i; std::cout << answer << "\n";
}

