#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n, k;
    if (!(std::cin >> n >> k)) { return 1; }
    std::vector<int> a;
    int value;
    while (std::cin >> value) { a.push_back(value); }
    std::vector<int> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + a[i];
    }
    for (int q = 0; q < k; q++) {
        int left = a[n + 2 * q];
        int right = a[n + 2 * q + 1];
        std::cout << prefix[right] - prefix[left] << "\n";
    }
    return 0;
}

