#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n, k;
    if (!(std::cin >> n >> k)) { return 1; }
    std::vector<int> a;
    int value;
    while (std::cin >> value) { a.push_back(value); }
    std::vector<int> distance(n, -1);
    std::vector<int> queue(n, 0);
    int head = 0;
    int tail = 0;
    distance[k] = 0;
    queue[tail] = k;
    tail++;
    while (head < tail) {
        int vertex = queue[head];
        head++;
        for (int next = 0; next < n; next++) {
            if (a[vertex * n + next] != 0 && distance[next] == -1) {
                distance[next] = distance[vertex] + 1;
                queue[tail] = next;
                tail++;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        std::cout << distance[i] << "\n";
    }
    return 0;
}

