#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n, k;
    if (!(std::cin >> n >> k)) { return 1; }
    std::vector<int> a;
    int value;
    while (std::cin >> value) { a.push_back(value); }
    std::vector<int> distance(n, 1000000000);
    std::vector<int> used(n, 0);
    distance[k] = 0;
    for (int step = 0; step < n; step++) {
        int vertex = -1;
        for (int i = 0; i < n; i++) {
            if (used[i] == 0) {
                if (vertex == -1 || distance[i] < distance[vertex]) {
                    vertex = i;
                }
            }
        }
        if (vertex == -1 || distance[vertex] == 1000000000) {
            break;
        }
        used[vertex] = 1;
        for (int next = 0; next < n; next++) {
            int weight = a[vertex * n + next];
            if (weight >= 0 && used[next] == 0) {
                distance[next] = std::min(distance[next], distance[vertex] + weight);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        int value = distance[i];
        if (value == 1000000000) {
            value = -1;
        }
        std::cout << value << "\n";
    }
    return 0;
}

